package local.paladinclient;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import java.util.stream.Stream;import com.google.gson.*;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.inventory.InventoryScreen;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.effect.*;import net.minecraft.world.item.*;import net.minecraft.server.level.ServerPlayer;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.puffish.skillsmod.api.*;import net.spell_engine.internals.*;import net.spell_power.api.*;
@Mod(value="paladin_client_probe",dist=Dist.CLIENT) public class PaladinClientProbe {
 final List<String> results=Collections.synchronizedList(new ArrayList<>());final AtomicReference<String> pending=new AtomicReference<>();int ticks,phase,at;boolean hidden,done;UUID casterID;
 interface Work{void run(ServerPlayer p)throws Exception;}void check(boolean b,String s){results.add((b?"PASS ":"FAIL ")+s);}void near(double a,double b,String s){check(Math.abs(a-b)<.015,s+" actual="+a+" expected="+b);}
 Category cat(){return SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow();}
 void server(Work work){var mc=Minecraft.getInstance();pending.set("waiting");mc.getSingleplayerServer().execute(()->{try{work.run(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));pending.set("ready");}catch(Throwable e){e.printStackTrace();check(false,"server exception "+e);pending.set("failed");}});}
 void next(){phase++;at=ticks;}void shot(String s){Screenshot.grab(Minecraft.getInstance(),false);results.add("SCREENSHOT "+s);}
 List<String> description(String id)throws Exception{var effect=Minecraft.getInstance().player.getEffect(PaladinRevamp.effect(id));check(effect!=null,"active client effect "+id);var type=Class.forName("fuzs.effectinsights.common.client.gui.tooltip.MobEffectTooltipLines");var extractor=type.getField("DESCRIPTION").get(null);var method=extractor.getClass().getMethod("getTooltipLines",Object.class,int.class);method.setAccessible(true);return ((Stream<Component>)method.invoke(extractor,effect,210)).map(Component::getString).toList();}
 void inventory()throws Exception{var mc=Minecraft.getInstance();mc.setScreenAndShow(new InventoryScreen(mc.player));double x=mc.getWindow().getGuiScaledWidth()/2d+100,y=(mc.getWindow().getGuiScaledHeight()-166)/2d+12;for(String f:List.of("xpos","ypos")){var field=mc.mouseHandler.getClass().getDeclaredField(f);field.setAccessible(true);field.setDouble(mc.mouseHandler,(f.equals("xpos")?x:y)*mc.getWindow().getGuiScale());}}
 public PaladinClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);}
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(!hidden){org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().handle());mc.options.pauseOnLostFocus=false;hidden=true;}if(done||mc.player==null||mc.level==null)return;mc.mouseHandler.releaseMouse();ticks++;
 try{
  if(ticks>1600)throw new AssertionError("timeout phase="+phase);
  if(phase==0&&ticks>=30){server(p->{p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);for(var old:p.level().getEntitiesOfClass(net.minecraft.world.entity.Mob.class,p.getBoundingBox().inflate(200)))old.discard();p.getFoodData().setFoodLevel(20);for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)p.level().setBlockAndUpdate(new net.minecraft.core.BlockPos(x,100,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());p.teleportTo(.5,101,.5);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.getInventory().clearContent();for(var slot:EquipmentSlot.VALUES)if(slot.isArmor())p.setItemSlot(slot,ItemStack.EMPTY);p.removeAllEffects();PaladinRevamp.clear(p);var c=cat();c.unlock(p);c.resetSkills(p);c.setExtraPoints(p,1000);for(String n:List.of("tdimeso8ajcwiygp","jrammznsez4yabio","ker4ssz0dfk2l06w"))c.getSkill(n).orElseThrow().unlock(p);p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(100);p.getAttribute(SpellSchools.HEALING.attributeEntry).setBaseValue(20);p.getAttribute(Attributes.ARMOR).setBaseValue(20);p.getAttribute(SpellPowerMechanics.CRITICAL_CHANCE.attributeEntry).setBaseValue(0);p.setHealth(p.getMaxHealth());});next();return;}
  if(phase==0||ticks-at<25||"waiting".equals(pending.get()))return;if("failed".equals(pending.get())){finish();return;}
  switch(phase){
   case 1->{server(p->PaladinRevamp.protect(p.level(),PaladinRevamp.spell(p,"paladins:divine_protection"),p,List.of(),new SpellExecution.ImpactContext(),null));next();}
   case 2->{var lines=description(PaladinRevamp.DP);check(String.join(" ",lines).contains("50%"),"Effect Insights renders received50% damage reduction "+lines);check(String.join(" ",description(PaladinRevamp.KR)).contains("80%"),"Effect Insights renders received80%KR");server(p->near(p.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE),.8,"server-authoritativeKR80%"));inventory();next();}
   case 3->{shot("received Protection effect tooltip");mc.setScreenAndShow(null);server(p->{p.removeAllEffects();PaladinRevamp.clear(p);var caster=net.neoforged.neoforge.common.util.FakePlayerFactory.get(p.level(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"OtherCaster"));casterID=caster.getUUID();var snapshot=new JsonObject();snapshot.addProperty("p",8);snapshot.addProperty("m",20);snapshot.addProperty("armor",30);snapshot.addProperty("caster",casterID.toString());PaladinRevamp.landOath(caster,p,snapshot);EffectDetails.update(p);});next();}
   case 4->{var lines=String.join(" ",description(PaladinRevamp.OATH));check(lines.contains("+3 per hit"),"other caster M20 resolves+3 not recipientM100 "+lines);check(lines.contains("Armor: +8"),"other caster armor30 resolves+8");check(lines.contains("3.2 HP"),"other caster P8 resolves3.2absorption");inventory();next();}
   case 5->{shot("caster-resolved Oath tooltip");mc.setScreenAndShow(null);server(p->{p.setAbsorptionAmount(1);var snapshot=new JsonObject();snapshot.addProperty("p",8);snapshot.addProperty("m",20);snapshot.addProperty("armor",30);snapshot.addProperty("caster",casterID.toString());PaladinRevamp.landOath(p,p,snapshot);EffectDetails.update(p);});next();}
   case 6->{near(mc.player.getAbsorptionAmount(),1,"client absorption refresh preserves spent HP");check(String.join(" ",description(PaladinRevamp.OATH)).contains("remaining: 1 HP"),"tooltip reports currentremaining1HP");server(p->{p.removeAllEffects();PaladinRevamp.clear(p);cat().resetSkills(p);cat().getSkill("tdimeso8ajcwiygp").orElseThrow().unlock(p);p.addEffect(new MobEffectInstance(PaladinRevamp.effect("spell_engine:stun"),200));});next();}
   case 7->{check(!((net.combat_roll.internals.RollingEntity)mc.player).getRollManager().isRollAvailable(mc.player),"native client roll manager blocks stun without node");check(String.join(" ",description("spell_engine:stun")).contains("Stunned"),"official stun details resolved");inventory();next();}
   case 8->{shot("official stun icon and details");mc.setScreenAndShow(null);server(p->{p.removeAllEffects();cat().getSkill("19retxukpiocfea2").orElseThrow().unlock(p);p.addEffect(new MobEffectInstance(PaladinRevamp.effect("wizards:frozen"),200));});next();}
   case 9->{check(((net.combat_roll.internals.RollingEntity)mc.player).getRollManager().isRollAvailable(mc.player),"native client roll manager allows selected ready Break Restriction");check(String.join(" ",description("wizards:frozen")).contains("Frozen"),"official frozen details resolved");inventory();next();}
   case 10->{shot("official frozen icon and details");mc.setScreenAndShow(null);net.combat_roll.client.Keybindings.roll.setDown(true);results.add("ROLL INPUT ground="+mc.player.onGround()+" food="+mc.player.getFoodData().getFoodLevel()+" screen="+mc.gui.screen()+" available="+((net.combat_roll.internals.RollingEntity)mc.player).getRollManager().isRollAvailable(mc.player));for(var method:Minecraft.class.getDeclaredMethods())if(method.getName().endsWith("tryRolling")){method.setAccessible(true);method.invoke(mc);}next();}
   case 11->{net.combat_roll.client.Keybindings.roll.setDown(false);check(!mc.player.hasEffect(PaladinRevamp.effect("wizards:frozen")),"actual roll key event cleanses frozen on server andclient");server(p->{p.removeAllEffects();p.addEffect(new MobEffectInstance(PaladinRevamp.effect("rogues:bear_trap"),200));});next();}
   case 12->{check(!((net.combat_roll.internals.RollingEntity)mc.player).getRollManager().isRollAvailable(mc.player),"cooling Break Restriction cannot escape root");check(String.join(" ",description("rogues:bear_trap")).contains("Rooted"),"official root details resolved");inventory();next();}
   case 13->{shot("official root icon and details");mc.setScreenAndShow(null);server(p->{p.removeAllEffects();PaladinRevamp.clear(p);PaladinRevamp.launchOath(p.level(),PaladinRevamp.spell(p,"paladins:judgement"),p,List.of(),new SpellExecution.ImpactContext(),null);});next();}
   case 14->{check(mc.player.hasEffect(PaladinRevamp.effect(PaladinRevamp.OATH)),"native falling hammer completes and blesses real player");check(net.minecraft.client.resources.language.I18n.get("spell.paladins.judgement.name").equals("Divine Oath"),"skill and scroll name Divine Oath");server(p->{p.removeAllEffects();PaladinRevamp.clear(p);p.addEffect(new MobEffectInstance(PaladinRevamp.effect("skill_tree_rpgs:chastise"),100,9));p.addEffect(new MobEffectInstance(PaladinRevamp.effect("skill_tree_rpgs:berserker"),100,4));EffectDetails.update(p);});next();}
   case 15->{check(String.join(" ",description("skill_tree_rpgs:berserker")).contains("+50%"),"Warrior custom basicattack bonus resolves50%");inventory();next();}
   case 16->{shot("cross-class buff and debuff details");finish();}
  }
 }catch(Throwable e){e.printStackTrace();check(false,"client exception "+e);finish();}}
 void finish(){done=true;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("client-checks.txt"),results);Files.writeString(mc.gameDirectory.toPath().resolve("client-result.txt"),(results.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS")+" "+results.stream().filter(s->s.startsWith("PASS")).count()+" checks\n");}catch(Exception e){throw new RuntimeException(e);}mc.stop();}
}
